  int size = 0;
  ShapeField.DecodedTriangle t = node.triangle;
  size += vLongSize((long) maxX - t.aX);
  size += vLongSize((long) maxY - t.aY);
  if (t.type == TYPE.LINE || t.type == TYPE.TRIANGLE) {
    size += vLongSize((long) maxX - t.bX);
    size += vLongSize((long) maxY - t.bY);
  }
