      int tMinX = bbox.minX;
      int tMaxX = bbox.maxX;
      int tMaxY = bbox.maxY;

      // relate the query to the shape bounding box
      Relation r;
      if ((r =
              query.relate(
                  encoder.decodeX(bbox.minX),
                  encoder.decodeX(bbox.maxX),
                  encoder.decodeY(bbox.minY),
                  encoder.decodeY(bbox.maxY)))
          != Relation.CELL_CROSSES_QUERY) {
